      "subject": {
        "description": "Stunning young woman",
        "features": [
          "Dark wavy hair",
          "Warm brown eyes",
          "Detailed skin texture",
          "Deep shadows on face"
        ],
        "clothing": [
          "Casual white tank top",
          "Comfortable lounge pants"
        ],
        "pose": "Sitting cross-legged on the floor, leaning back against the wall"
